import {API_BASE,escapeHTML as esc,sourceURL} from './cuenta/core.js';
const $=s=>document.querySelector(s);
let rows=[],selected=new Set(),request=0;
const MAX_AGE=30*86400000;
const normalize=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function verified(r){const age=Date.now()-Date.parse(r.last_checked_at);return r.status==='verified'&&r.link_status==='ok'&&age>=0&&age<=MAX_AGE;}
const options=(id,values)=>{const select=$('#training-'+id),old=select.value;select.length=1;[...new Set(values)].sort((a,b)=>a.localeCompare(b,'es')).forEach(v=>select.add(new Option(v,v)));select.value=old;};
async function load(){const ticket=++request;$('#training-status').textContent='Comprobando el catálogo…';try{const res=await fetch(API_BASE+'/api/training',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error();const data=await res.json();if(!Array.isArray(data))throw Error();if(ticket!==request)return;rows=data;options('area',rows.flatMap(r=>r.categories));options('region',rows.filter(r=>r.modes.some(m=>m!=='Online')).map(r=>r.region));selected=new Set([...selected].filter(id=>rows.some(r=>r.id===id)));render();}catch{if(ticket!==request)return;rows=[];selected.clear();$('#training-cards').replaceChildren();$('#training-overview').textContent='Catálogo temporalmente no disponible';$('#training-status').textContent='No se pudo actualizar la formación. Pulsa Actualizar datos para reintentar.';compare();}}
function card(r){const ok=verified(r);return `<article class="study" data-training-id="${esc(r.id)}"><div class="tags"><span class="badge ${ok?'verified':'pending'}">${ok?'Programa y enlace verificados':'Pendiente de revalidación'}</span><span class="badge">${esc(r.credential_type)}</span></div><h3>${esc(r.title)}</h3><p class="org">${esc(r.org)}</p><p>${esc(r.city)} · ${esc(r.modes.join(' / '))}<br>Centro: ${esc(r.provider_type)}</p><p>${esc(r.summary)}</p><dl><dt>Duración</dt><dd>${esc(r.duration)}</dd><dt>Título que obtienes</dt><dd>${esc(r.qualification)}</dd></dl><details><summary>Acceso, prácticas y coste</summary><dl><dt>Acceso</dt><dd>${esc(r.access)}</dd><dt>Prácticas</dt><dd>${esc(r.practice)}</dd><dt>Coste</dt><dd>${esc(r.cost)}</dd><dt>Admisión</dt><dd>${esc(r.admission_status)}</dd></dl></details><details><summary>Qué hemos comprobado</summary><p>${esc(r.evidence)}</p><p>${esc(r.link_note||'El enlace responde y corresponde a la formación publicada.')}</p>${(r.supporting_sources||[]).map(u=>`<a href="${esc(sourceURL(u))}" target="_blank" rel="noopener noreferrer">Fuente complementaria ↗</a>`).join('')}</details><div class="actions"><a href="${esc(sourceURL(r.source))}" target="_blank" rel="noopener noreferrer">Ver programa ↗</a><button type="button" data-compare="${esc(r.id)}" aria-pressed="${selected.has(r.id)}" aria-label="${selected.has(r.id)?'Quitar de la comparación':'Comparar'} ${esc(r.title)} en ${esc(r.org)}">${selected.has(r.id)?'Seleccionado':'Comparar'}</button></div><p class="checked">Revisado: ${esc(r.last_checked_at.slice(0,10))} · Plazas por confirmar</p></article>`;}
function render(){const value=id=>$('#training-'+id).value;const query=normalize(value('search'));
 const shown=rows.filter(r=>($('#training-pending').checked||verified(r))&&(!value('area')||r.categories.includes(value('area')))&&(!value('region')||r.region===value('region'))&&(!value('mode')||r.modes.includes(value('mode')))&&(!value('credential')||r.credential_type===value('credential'))&&(!value('provider')||r.provider_type===value('provider'))&&(!query||normalize([r.title,r.org,r.city,r.summary,...r.categories].join(' ')).includes(query)));
 const active=rows.filter(verified),regions=new Set(active.filter(r=>r.region!=='Online').map(r=>r.region));$('#training-overview').innerHTML=`<span>${active.length} programas verificados</span><span>${regions.size} comunidades con centros</span><span>${active.filter(r=>r.modes.includes('Online')).length} opciones online</span>`;
 $('#training-status').textContent=`${shown.length} programas encontrados · ${shown.filter(verified).length} verificados · matrícula por confirmar`;
 const groups=[...new Set(shown.map(r=>r.region))].sort((a,b)=>a==='Comunitat Valenciana'?-1:b==='Comunitat Valenciana'?1:a==='Online'?-1:b==='Online'?1:a.localeCompare(b,'es'));
 $('#training-cards').innerHTML=shown.length?groups.map(region=>{const items=shown.filter(r=>r.region===region);return `<section class="region-group"><h3 class="region-title">${esc(region)} <span>${items.length} opciones</span></h3><div class="cards">${items.map(card).join('')}</div></section>`;}).join(''):'<p class="empty">No hay programas con estos filtros. Prueba otra modalidad, limpia los filtros o consulta los directorios de tu comunidad al final de la página.</p>';
 compare();}
function compare(){const items=rows.filter(r=>selected.has(r.id));$('#training-compare').hidden=!items.length;$('#compare-bar').hidden=!items.length;$('#compare-count').textContent=`${items.length} de 3 opciones seleccionadas`;if(!items.length){$('#compare-table').replaceChildren();return;}
 const fields=[['Modalidad',r=>r.modes.join(' / ')],['Lugar',r=>r.city+' · '+r.region],['Centro',r=>r.provider_type],['Titulación',r=>r.credential_type+' · '+r.qualification],['Duración',r=>r.duration],['Acceso',r=>r.access],['Prácticas',r=>r.practice],['Coste',r=>r.cost],['Admisión',r=>r.admission_status],['Verificación',r=>(verified(r)?'Verificado':'Pendiente de revalidación')+' · '+r.last_checked_at.slice(0,10)]];
 $('#compare-table').innerHTML=`<caption class="small">Comparación de ${items.length} programas seleccionados</caption><thead><tr><th scope="col">Qué comparar</th>${items.map(r=>`<th scope="col">${esc(r.title)}<br><small>${esc(r.org)}</small></th>`).join('')}</tr></thead><tbody>${fields.map(([label,get])=>`<tr><th scope="row">${label}</th>${items.map(r=>`<td>${esc(get(r))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Más información</th>${items.map(r=>`<td><a href="${esc(sourceURL(r.source))}" target="_blank" rel="noopener noreferrer">Ver programa ↗</a></td>`).join('')}</tr></tbody>`;}
$('#training-filters').onsubmit=e=>e.preventDefault();$('#training-search').oninput=render;['area','region','mode','credential','provider','pending'].forEach(id=>$('#training-'+id).onchange=render);$('#training-reset').onclick=()=>{$('#training-filters').reset();render();};$('#training-retry').onclick=load;$('#compare-clear').onclick=()=>{selected.clear();render();};
$('#training-cards').onclick=e=>{const button=e.target.closest('[data-compare]');if(!button)return;const id=button.dataset.compare;if(selected.has(id))selected.delete(id);else if(selected.size<3)selected.add(id);else{$('#training-status').textContent='Puedes comparar hasta 3 programas. Quita uno antes de añadir otro.';return;}const pressed=selected.has(id);button.setAttribute('aria-pressed',String(pressed));button.textContent=pressed?'Seleccionado':'Comparar';const r=rows.find(r=>r.id===id);button.setAttribute('aria-label',`${pressed?'Quitar de la comparación':'Comparar'} ${r.title} en ${r.org}`);compare();};
setInterval(()=>{if(rows.length)render();},60000);load();
